import {mountVoxProFace} from './vox-pro-face.js';
import {voxWarmTransfer} from './vox-warm-model.js';
export const WARM_BANKS=Object.freeze([['HARMONICS',['drive','bias']],['FILTER',['tone']],['PARALLEL / OUTPUT',['mix','output']]]);
const graph='<svg viewBox="0 0 360 182" role="img" aria-label="Courbe statique de saturation"><rect x="1" y="1" width="358" height="180" rx="4" fill="#171520" stroke="#716782"/>'+[-1,-.5,0,.5,1].map(v=>'<path d="M'+(180+v*152)+' 14V162 M28 '+(88-v*74)+'H332" stroke="'+(v===0?'#9387a4':'#393445')+'"/>').join('')+'<path d="M28 162L332 14" stroke="#84789c" stroke-dasharray="4 4"/><path data-warm-curve fill="none" stroke="#d6b1f4" stroke-width="2.5"/><text x="180" y="174" text-anchor="middle" fill="#d5cbe8" font-size="9">INPUT / STATIC TRANSFER</text></svg>';
export function mountVoxWarm(root,options){return mountVoxProFace(root,{...options,id:'vox-warm',title:'WARM 07',subtitle:'VOCAL HARMONICS · 4× OVERSAMPLING',banks:WARM_BANKS,display:graph+'<div class="vox-pro-readouts"><output data-warm-drive></output><output data-warm-bias></output><output data-warm-status></output></div><small>Fonction statique du WaveShaper avant filtres, suréchantillonnage, mix et trim. Pas un oscilloscope ni une mesure de distorsion harmonique.</small>',footer:'4× OVERSAMPLING · DC BLOCK 24 Hz · WET OUTPUT TRIM',paint(face,s){
 const fn=voxWarmTransfer(s.drive,s.bias);face.querySelector('[data-warm-curve]').setAttribute('d',Array.from({length:161},(_,i)=>{const x=i/80-1;return (i?'L':'M')+(180+x*152).toFixed(2)+' '+(88-fn(x)*74).toFixed(2);}).join(''));
 face.querySelector('[data-warm-drive]').textContent='DRIVE '+s.drive.toFixed(1)+' dB';face.querySelector('[data-warm-bias]').textContent='BIAS '+Math.round(s.bias*100)+'%';face.querySelector('[data-warm-status]').textContent=s.enabled===false?'BYPASS':s.mix===0?'DRY':'ACTIVE';
 }});}
